OmniUiCard.stylingConfiguration:
{"styleObjects":{},"customStyles":".block-header-heading{
 width: 100% !important; 
 background-color: #f3f3f3;
 height: 38px;
}

.slds-form-element__label{
 padding-bottom:10px;
 color: #7E8C8D;
 font-size: 13px;
}

.field-value{
 margin-top: 1px;
 display: block;
}

.field-display{
 height: 50px;
 padding-left:10px;
 padding-top:5px;
 margin-bottom: 5px;
}

.blockSlot{
 padding-left: 4px;
 padding-top: 4px;
 padding-bottom: 3px;
}

/* Outer banner */
.water-advisory-banner {
 display: flex;
 align-items: center;
 background: #fdb913;
 color: #111;
 padding: 12px 24px;
 width: 100%;
 border: none;
 box-shadow: none;
}

/* Row container */
.wateradvisoryrow {
 display: flex !important;
 align-items: center;
}

/* Icon container */
.WaterAdvisoryBannerBlockIconContainer {
 width: 20px !important;
 min-width: 20px !important;
 flex: 0 0 20px !important;

 display: flex;
 align-items: center;
 justify-content: center;

 margin-right: 10px;
 padding: 0 !important;

 align-self: center;
}

/* Warning icon */
.WaterAdvisoryBannerBlockWarningIcon {
 width: 16px !important;
 height: 16px !important;

 fill: #000 !important;
 color: #000 !important;

 display: block;
 margin: auto;

 opacity: 1 !important;
 filter: none !important;
}

/* Experience Site SVG override */
.WaterAdvisoryBannerBlockWarningIcon svg,
.WaterAdvisoryBannerBlockWarningIcon lightning-primitive-icon svg {
 fill: #000 !important;
}

/* Text container */
.water-advisory-content {
 display: flex;
 flex-direction: column;
 flex: 1;
 padding: 0 !important;
 margin: 0 !important;
}

/* Title */
.water-advisory-title {
 font-weight: 700;
 font-size: 14px;
 line-height: 1.25;
 margin: 0;
 color: #111;
}

/* Reason text */
.water-advisory-reason {
 font-size: 13px;
 line-height: 1.25;
 margin-top: 2px;
 color: #111;
}

.detailLabel {
 font-size: 14px;
 font-weight: 649;
 color: #000000;
 line-height: 1.4;
 	font-weight: bold;
}

.headerFacilityLabel {
 font-size: 0.875rem;
 font-weight: 400;
 color: #181818;
 line-height: 1.25;
 margin-bottom: 0.35rem;
}

.facilityName {
 font-size: 20pt;
 font-weight: 500;
 line-height: 1;
 color: #003366;
 margin: 0;
 padding: 0;
}

.detailValue {
 font-size: 14px;
 font-weight: 400;
 color: #000000;
 line-height: 1.4;
}

.custom-bottom-gap {
 padding-top: 10px !important; 
 	padding-bottom: 10px !important;
 padding-left: 10px !important;
 padding-right: 10px !important;
}

.custom-gap {
 	margin-top: 12px !important;
}

.collapsible-title .blockLabel {
 font-weight: 700;
}
"}
